"""Turns one raw health-check response into one of five outcomes (D22). Pure function, no I/O."""
from enum import Enum


class Outcome(str, Enum):
    OK_FAST = "OK_FAST"                # 2xx within the slow threshold
    OK_SLOW = "OK_SLOW"                # 2xx, but slower than the slow threshold
    FAIL_HTTP = "FAIL_HTTP"            # answered, but not 2xx (e.g. 503, 500, 302)
    FAIL_TIMEOUT = "FAIL_TIMEOUT"      # no answer within the timeout
    FAIL_CONNECTION = "FAIL_CONNECTION"  # could not connect at all (DNS, refused, reset)


SUCCESS_OUTCOMES = {Outcome.OK_FAST, Outcome.OK_SLOW}


def is_success(outcome: Outcome) -> bool:
    return outcome in SUCCESS_OUTCOMES


def classify(http_status: int | None, response_time_ms: int | None, error_kind: str | None,
             slow_threshold_ms: int) -> Outcome:
    """error_kind is set by the probe: "timeout", "connection", or None when we got an HTTP answer."""
    if error_kind == "timeout":
        return Outcome.FAIL_TIMEOUT
    if error_kind == "connection":
        return Outcome.FAIL_CONNECTION
    if http_status is None or not 200 <= http_status < 300:
        return Outcome.FAIL_HTTP
    if response_time_ms is not None and response_time_ms > slow_threshold_ms:
        return Outcome.OK_SLOW
    return Outcome.OK_FAST

"""The service state machine (DESIGN.md section 5). Pure function, no I/O, fully unit-tested.

Given the previous state, the counters and the outcome of the newest check, it returns the
new state, the new counters and which incident actions the caller must perform.
"""
from dataclasses import dataclass

from app.domain.classify import Outcome, is_success

HEALTHY, DEGRADED, DOWN, RECOVERING, UNKNOWN = "HEALTHY", "DEGRADED", "DOWN", "RECOVERING", "UNKNOWN"

FAILURE_REASON = {
    Outcome.FAIL_HTTP: "http_error",
    Outcome.FAIL_TIMEOUT: "timeout",
    Outcome.FAIL_CONNECTION: "connection_error",
}


@dataclass(frozen=True)
class Rules:
    failure_threshold: int = 2   # consecutive failures before DOWN (PO)
    recovery_threshold: int = 3  # consecutive successes before recovered (PO)


@dataclass(frozen=True)
class Transition:
    status: str
    reason: str | None
    consecutive_failures: int
    consecutive_successes: int
    open_incident: bool = False          # entered DOWN from a non-outage state
    resolve_incidents: bool = False      # recovery confirmed
    recovery_progress: bool = False      # a success while DOWN/RECOVERING, not yet confirmed
    recovery_interrupted: bool = False   # a failure while RECOVERING (D24)


def _available_state(outcome: Outcome, is_flaky: bool) -> tuple[str, str | None]:
    """State of a service that is answering successfully (not in an outage)."""
    if is_flaky:
        return DEGRADED, "flaky"
    if outcome == Outcome.OK_SLOW:
        return DEGRADED, "slow_response"
    return HEALTHY, None


def next_state(prev_status: str, consecutive_failures: int, consecutive_successes: int,
               outcome: Outcome, is_flaky: bool, rules: Rules) -> Transition:
    success = is_success(outcome)
    if success:
        fails, succ = 0, consecutive_successes + 1
    else:
        fails, succ = consecutive_failures + 1, 0

    in_outage = prev_status in (DOWN, RECOVERING)

    if in_outage:
        if not success:
            # Still down, or recovery interrupted: same outage, same incident, no new one (D24).
            return Transition(DOWN, FAILURE_REASON[outcome], fails, succ,
                              recovery_interrupted=(prev_status == RECOVERING))
        if succ >= rules.recovery_threshold:
            status, reason = _available_state(outcome, is_flaky)
            return Transition(status, reason, fails, succ, resolve_incidents=True)
        return Transition(RECOVERING, "recovering", fails, succ, recovery_progress=True)

    # Not in an outage: UNKNOWN, HEALTHY or DEGRADED.
    if not success:
        if fails >= rules.failure_threshold:
            return Transition(DOWN, FAILURE_REASON[outcome], fails, succ, open_incident=True)
        return Transition(DEGRADED, "flaky" if is_flaky else FAILURE_REASON[outcome], fails, succ)

    status, reason = _available_state(outcome, is_flaky)
    return Transition(status, reason, fails, succ)

"""All human-facing text: customer-safe public wording and webhook payloads. Pure functions.

D30: public text is built ONLY from these fixed templates. Nothing here ever receives the raw
error message from a health check, so internal details (IPs, DB hosts) cannot leak.
"""
from datetime import datetime

from app.domain.classify import Outcome

PUBLIC_LABEL = {
    "HEALTHY": "Operational",
    "DEGRADED": "Degraded performance",
    "DOWN": "Service disruption",
    "RECOVERING": "Recovering",
    "UNKNOWN": "No data yet",
}


def display_name(service_name: str) -> str:
    return service_name.replace("-", " ").replace("_", " ").title()


def public_status_message(service_name: str, status: str) -> str:
    name = display_name(service_name)
    return {
        "HEALTHY": f"{name} is operating normally.",
        "DEGRADED": f"{name} is experiencing delays. Some requests may be slower than usual or fail intermittently.",
        "DOWN": f"{name} is currently unavailable for some customers. Our engineering team is investigating the issue.",
        "RECOVERING": f"A fix is in place and {name} is recovering. We are monitoring it closely.",
        "UNKNOWN": f"We have not collected status information for {name} yet.",
    }[status]


def public_incident_message(service_name: str) -> str:
    name = display_name(service_name)
    return (f"{name} is currently experiencing problems. Some customers may be unable to use it. "
            "Our engineering team is investigating the issue.")


PUBLIC_UPDATE = {
    "opened": "Investigating: we are aware of a problem with {name} and are looking into it.",
    "recovering": "Monitoring: {name} is responding again. We are confirming the recovery.",
    "resolved": "Resolved: {name} has recovered and is operating normally.",
}


def public_update(kind: str, service_name: str) -> str:
    return PUBLIC_UPDATE[kind].format(name=display_name(service_name))


def describe_failure(outcome: Outcome, http_status: int | None, timeout_ms: int) -> str:
    """A short failure CATEGORY for engineers and webhooks. Never the raw error body."""
    if outcome == Outcome.FAIL_TIMEOUT:
        return f"timed out after {timeout_ms} ms"
    if outcome == Outcome.FAIL_CONNECTION:
        return "connection failed"
    return f"HTTP {http_status}"


def _iso(ts: datetime) -> str:
    return ts.isoformat().replace("+00:00", "Z")


def incident_code(incident_id: int) -> str:
    return f"INC-{incident_id:04d}"


def webhook_payload(event: str, *, notification_id: int, incident_id: int, service: str, severity: str,
                    status: str, message: str, started_at: datetime, timestamp: datetime,
                    resolved_at: datetime | None = None) -> dict:
    payload = {
        "event_id": f"ntf-{notification_id}",
        "event": event,
        "incident_id": incident_code(incident_id),
        "service": service,
        "severity": severity,
        "status": status,
        "message": message,
        "started_at": _iso(started_at),
        "timestamp": _iso(timestamp),
    }
    if resolved_at is not None:
        payload["resolved_at"] = _iso(resolved_at)
        payload["duration_seconds"] = int((resolved_at - started_at).total_seconds())
    return payload

