Operator pages need a login; /status is public and renders ONLY the PublicStatus schema,
the same customer-safe model the public API returns.
"""
from datetime import datetime, timedelta, timezone
from pathlib import Path

from fastapi import APIRouter, Depends, Form, Request
from fastapi.responses import HTMLResponse, RedirectResponse
from fastapi.templating import Jinja2Templates
from sqlalchemy import select
from sqlalchemy.orm import Session

from app import incidents, reporting
from app.auth import check_credentials, current_user, require_operator_page
from app.catalog import ConfigError, create_service, update_service
from app.config import TIER_INTERVAL_SECONDS, Settings
from app.domain.messages import PUBLIC_LABEL, incident_code
from app.models import Incident, Service
from app.routes.deps import get_db, get_settings
from app.schemas import ServiceCreate, ServiceUpdate

router = APIRouter(include_in_schema=False)
templates = Jinja2Templates(directory=str(Path(__file__).resolve().parent.parent / "templates"))


# ---------------- template helpers ----------------
def configure_templates(settings: Settings) -> None:
    tz = timezone(timedelta(minutes=settings.display_utc_offset_minutes))
    tz_label = "IST" if settings.display_utc_offset_minutes == 330 else "local"

    def fmt_time(value: datetime | None, with_date: bool = False) -> str:
        if value is None:
            return "–"
        fmt = "%d %b %H:%M:%S" if with_date else "%H:%M:%S"
        return value.astimezone(tz).strftime(fmt) + f" {tz_label}"

    templates.env.filters["t"] = fmt_time
    templates.env.filters["td"] = lambda v: fmt_time(v, True)
    templates.env.filters["dur"] = human_duration
    templates.env.globals["incident_code"] = incident_code
    templates.env.globals["PUBLIC_LABEL"] = PUBLIC_LABEL


def human_duration(seconds: float | None) -> str:
    if seconds is None:
        return "–"
    seconds = int(seconds)
    if seconds < 60:
        return f"{seconds}s"
    if seconds < 3600:
        return f"{seconds // 60}m {seconds % 60}s"
    return f"{seconds // 3600}h {(seconds % 3600) // 60}m"


def latency_chart(points: list, width: int = 640, height: int = 140) -> dict:
    """SVG polyline points for response times. Failed checks are drawn as red markers."""
    if not points:
        return {"line": "", "fails": [], "max_ms": 0, "width": width, "height": height}
    max_ms = max([p[1] or 0 for p in points] + [100])
    step = width / max(len(points) - 1, 1)
    line, fails = [], []
    for i, (_, ms, ok) in enumerate(points):
        x = round(i * step, 1)
        y = round(height - (ms or 0) / max_ms * (height - 10), 1)
        if ok:
            line.append(f"{x},{y}")
        else:
            fails.append(x)
    return {"line": " ".join(line), "fails": fails, "max_ms": max_ms, "width": width, "height": height}


def render(request: Request, name: str, **ctx) -> HTMLResponse:
    return templates.TemplateResponse(request, name, {"user": current_user(request), **ctx})


# ---------------- login ----------------
@router.get("/login")
def login_page(request: Request, next: str = "/"):
    return render(request, "login.html", next=next, error=None)


@router.post("/login")
def login_submit(request: Request, username: str = Form(...), password: str = Form(...), next: str = Form("/"),
                 settings: Settings = Depends(get_settings)):
    if not check_credentials(username, password, settings):
        return render(request, "login.html", next=next, error="Invalid username or password")
    request.session["user"] = username
    safe_next = next if next.startswith("/") and not next.startswith("//") else "/"  # no open redirect
    return RedirectResponse(safe_next, status_code=303)


@router.post("/logout")
def logout(request: Request):
    request.session.clear()
    return RedirectResponse("/status", status_code=303)


# ---------------- operator dashboard ----------------
@router.get("/")
def dashboard(request: Request, db: Session = Depends(get_db), settings: Settings = Depends(get_settings),
              user: str = Depends(require_operator_page)):
    services = list(db.scalars(select(Service).order_by(Service.name)))
    rows = []
    for svc in services:
        last = reporting.recent_checks(db, svc.id, limit=1)
        rows.append({"svc": svc, "rel": reporting.service_reliability(db, svc, settings),
                     "last": last[0] if last else None,
                     "chart": latency_chart(reporting.response_time_series(db, svc.id, 30), 160, 30)})
    return render(request, "dashboard.html", rows=rows, summary=reporting.dashboard_summary(db),
                  active=reporting.list_incidents(db, "active"), recent=reporting.list_incidents(db, limit=15),
                  metrics=reporting.metrics_summary(db))


# ---------------- services ----------------
@router.get("/services/new")
def new_service_page(request: Request, user: str = Depends(require_operator_page)):
    return render(request, "service_new.html", tiers=TIER_INTERVAL_SECONDS, errors=[], form={})


@router.post("/services/new")
async def new_service_submit(request: Request, db: Session = Depends(get_db),
                             settings: Settings = Depends(get_settings), user: str = Depends(require_operator_page)):
