    try:
        data = ServiceCreate(name=form.get("name", "").strip(), description=form.get("description", ""),
                             health_url=form.get("health_url", "").strip(), owner=form.get("owner", "").strip(),
                             criticality=form.get("criticality", "medium"))
        svc = create_service(db, data, settings)
        db.commit()
    except ConfigError as e:
        return render(request, "service_new.html", tiers=TIER_INTERVAL_SECONDS, errors=e.errors, form=form)
    except ValueError as e:   # pydantic validation error
        return render(request, "service_new.html", tiers=TIER_INTERVAL_SECONDS, errors=[str(e)], form=form)
    return RedirectResponse(f"/services/{svc.id}", status_code=303)


