{% extends "base.html" %}
{% block title %}{{ inc.code }}{% endblock %}
{% block content %}
<h1>{{ inc.code }} · <a href="/services/{{ inc.service_id }}">{{ inc.service_name }}</a>
  <span class="badge {{ inc.status }}">{{ inc.status }}</span> <span class="muted small">{{ inc.severity }}</span></h1>
<p><b>{{ inc.title }}</b></p>
{% if error %}<div class="alert bad">{{ error }}</div>{% endif %}

<div class="tiles">
  <div class="card tile"><div class="n small">{{ inc.first_failure_at|td }}</div><div class="l">First failed check</div></div>
  <div class="card tile"><div class="n small">{{ inc.opened_at|td }}</div><div class="l">Opened (detection {{ (inc.opened_at - inc.first_failure_at).total_seconds()|dur }})</div></div>
  <div class="card tile"><div class="n small">{{ inc.acknowledged_at|td }}</div><div class="l">Acknowledged{% if inc.acknowledged_by %} by {{ inc.acknowledged_by }}{% endif %}</div></div>
  <div class="card tile"><div class="n small">{{ inc.resolved_at|td }}</div><div class="l">Resolved{% if inc.resolved_at %} (after {{ (inc.resolved_at - inc.opened_at).total_seconds()|dur }}){% endif %}</div></div>
</div>
<p class="muted small">Trigger: <span class="mono">{{ inc.trigger_type }}</span> · key <span class="mono">{{ inc.trigger_key }}</span></p>

{% if inc.status != "RESOLVED" %}
<div class="card" style="margin:12px 0">
  {% if inc.status == "OPEN" %}
  <form class="inline" method="post" action="/incidents/{{ inc.id }}/acknowledge"><button>Acknowledge</button></form>
  {% endif %}
  <form method="post" action="/incidents/{{ inc.id }}/notes" style="margin-top:10px">
    <label>Add an internal note (never shown to customers)<textarea name="note" rows="2" required maxlength="2000"></textarea></label>
    <p><button>Add note</button></p>
  </form>
  <p class="muted small">The incident resolves automatically after {{ "the configured number of" }} consecutive successful checks.</p>
</div>
{% endif %}

<h2>Timeline</h2>
<ul class="timeline card">
  {% for e in inc.timeline %}
  <li>
    <span class="mono">{{ e.at|td }}</span> &nbsp; <span class="kind">{{ e.kind }}{% if e.is_public %} <span class="badge Operational" title="shown on the public status page">public</span>{% endif %}</span>
    {{ e.text }}
    {% if e.details %}<div class="mono muted" style="margin-left:170px">
      {% if e.details.http_status %}HTTP {{ e.details.http_status }} · {% endif %}{% if e.details.response_time_ms is not none %}{{ e.details.response_time_ms }} ms · {% endif %}{{ e.details.outcome }}
      {% if e.details.error %}<div class="err">{{ e.details.error }}</div>{% endif %}</div>{% endif %}
  </li>
  {% endfor %}
</ul>

<h2>Webhook notifications</h2>
{% if inc.notifications %}
<table>
  <tr><th>Event</th><th>Delivery</th><th>Attempts</th><th>Last attempt</th><th>Last HTTP status</th><th>Last error</th></tr>
  {% for n in inc.notifications %}
  <tr><td>{{ n.event_type }}</td><td><span class="badge {{ n.delivery_status }}">{{ n.delivery_status }}</span></td>
      <td>{{ n.attempts }}</td><td>{{ n.last_attempt_at|td }}</td><td>{{ n.last_http_status or '–' }}</td><td class="mono">{{ n.last_error or '' }}</td></tr>
  {% endfor %}
</table>
{% else %}<p class="muted">None.</p>{% endif %}
{% endblock %}

