"""Serves the built React app (frontend/dist) from the same origin as the API.

Same origin = the session cookie just works, and no CORS configuration is needed.
React Router handles URLs like /services/3 in the browser, so every non-API GET returns index.html.
"""
from pathlib import Path

from fastapi import FastAPI, HTTPException
from fastapi.responses import FileResponse
from fastapi.staticfiles import StaticFiles

NOT_SPA_PREFIXES = ("api/", "docs", "redoc", "openapi.json", "healthz")


def mount_spa(app: FastAPI, dist_dir: str) -> bool:
    dist = Path(dist_dir)
    index = dist / "index.html"
    if not index.is_file():
        return False   # e.g. backend-only development or tests: the API still works

    app.mount("/assets", StaticFiles(directory=dist / "assets"), name="assets")

    @app.get("/{path:path}", include_in_schema=False)
    def spa(path: str):
        if path.startswith(NOT_SPA_PREFIXES):
            raise HTTPException(status_code=404, detail="Not found")
        file = (dist / path).resolve()
        # Real files in dist (favicon etc.), but never anything outside dist.
        if path and file.is_file() and file.is_relative_to(dist.resolve()):
            return FileResponse(file)
        return FileResponse(index, headers={"Cache-Control": "no-cache"})

    return True

