// TypeScript mirrors of the backend's Pydantic schemas (app/schemas.py) and report dicts.
// Timestamps arrive as ISO-8601 strings in UTC.

export type ServiceStatus = "UNKNOWN" | "HEALTHY" | "DEGRADED" | "DOWN" | "RECOVERING";
export type Criticality = "critical" | "high" | "medium" | "low";
export type IncidentStatus = "OPEN" | "ACKNOWLEDGED" | "RESOLVED";

export interface Service {
  id: number;
  name: string;
  description: string;
  health_url: string;
  owner: string;
  criticality: Criticality;
  check_interval_seconds: number;
  timeout_ms: number;
  slow_threshold_ms: number;
  failure_threshold: number;
  recovery_threshold: number;
  flaky_enabled: boolean;
  flaky_failure_count: number;
  flaky_window_seconds: number;
  reliability_target: number;
  enabled: boolean;
  current_status: ServiceStatus;
  status_reason: string | null;
  status_since: string | null;
  consecutive_failures: number;
  consecutive_successes: number;
  last_checked_at: string | null;
  last_success_at: string | null;
  last_failure_at: string | null;
}

export type ServiceConfig = Pick<
  Service,
  | "criticality" | "health_url" | "owner" | "check_interval_seconds" | "timeout_ms" | "slow_threshold_ms"
  | "failure_threshold" | "recovery_threshold" | "flaky_enabled" | "flaky_failure_count"
  | "flaky_window_seconds" | "reliability_target" | "enabled"
>;

export interface HealthCheck {
  id: number;
  scheduled_at: string;
  started_at: string;
  completed_at: string;
  outcome: "OK_FAST" | "OK_SLOW" | "FAIL_HTTP" | "FAIL_TIMEOUT" | "FAIL_CONNECTION";
  success: boolean;
  http_status: number | null;
  response_time_ms: number | null;
  error_message: string | null;
  resulting_status: ServiceStatus;
}

export interface Availability {
  total_checks: number;
  successful_checks: number;
  covered_minutes: number;
  window_minutes: number;
  sufficient: boolean;
  percent: number | null;
}

export interface ErrorBudget {
  allowed_minutes: number;
  used_minutes: number;
  remaining_minutes: number;
  remaining_percent: number | null;
  exhausted: boolean;
}

export interface Reliability {
  window_hours: number;
  availability: Availability;
  error_budget: ErrorBudget | null;
  target: number;
  meets_target: boolean | null;
  latency_avg_ms: number | null;
  latency_p50_ms: number | null;
  latency_p95_ms: number | null;
  flaky_episodes: number;
}

export interface Incident {
  id: number;
  code: string;
  service_id: number;
  service_name: string;
  trigger_type: string;
  trigger_key: string;
  title: string;
  severity: string;
  status: IncidentStatus;
  first_failure_at: string;
  opened_at: string;
  acknowledged_at: string | null;
  acknowledged_by: string | null;
  resolved_at: string | null;
}

export interface TimelineEntry {
  at: string;
  kind: string;
  text: string;
  is_public: boolean;
  details: { http_status?: number | null; response_time_ms?: number | null; outcome?: string; error?: string | null } | null;
}

export interface NotificationDelivery {
  event_type: string;
  delivery_status: "PENDING" | "DELIVERED" | "FAILED";
  attempts: number;
  last_attempt_at: string | null;
  last_http_status: number | null;
  last_error: string | null;
}

export interface IncidentDetail extends Incident {
  timeline: TimelineEntry[];
  notifications: NotificationDelivery[];
}

export interface DashboardServiceRow {
  service: Service;
  reliability: Reliability;
  last_check: HealthCheck | null;
  recent: { at: string; ms: number | null; ok: boolean }[];
}

export interface DashboardSummary {
  total_services: number;
  by_status: Record<ServiceStatus, number>;
  active_incidents: Incident[];
  recent_incidents: Incident[];
  services: DashboardServiceRow[];
}

export interface MetricsSummary {
  incidents_total: number;
  mttd_seconds: number | null;
  mtta_seconds: number | null;
  mttr_seconds: number | null;
  checks_24h: number;
  check_success_rate_24h: number | null;
  avg_response_ms_24h: number | null;
  check_duration_avg_ms_1h: number | null;
  scheduler_lag_p95_ms_1h: number | null;
  notifications: { delivered: number; failed: number; pending: number };
  notification_success_rate: number | null;
  flaky_episodes_24h: number;
}

// ---- public (customer-safe) ----
export interface PublicIncident {
  id: string;
  service: string;
  message: string;
  state: "Investigating" | "Recovering" | "Resolved";
  started_at: string;
  resolved_at: string | null;
  duration_minutes: number | null;
  latest_update: { at: string; text: string } | null;
}

export interface PublicService {
  name: string;
  status: string;
  message: string;
  since: string | null;
  active_incidents: PublicIncident[];
}

export interface PublicStatus {
  overall: string;
  updated_at: string;
  services: PublicService[];
}

export interface PublicHistory {
  days: number;
  incidents: PublicIncident[];
}

