// TypeScript mirrors of the backend's Pydantic schemas (app/schemas.py) and report dicts.
// Timestamps arrive as ISO-8601 strings in UTC.

export type ServiceStatus = "UNKNOWN" | "HEALTHY" | "DEGRADED" | "DOWN" | "RECOVERING";
export type Criticality = "critical" | "high" | "medium" | "low";
export type IncidentStatus = "OPEN" | "ACKNOWLEDGED" | "RESOLVED";

export interface Service {
  id: number;
  name: string;
  description: string;
  health_url: string;
  owner: string;
  criticality: Criticality;
  check_interval_seconds: number;
  timeout_ms: number;
  slow_threshold_ms: number;
  failure_threshold: number;
  recovery_threshold: number;
  flaky_enabled: boolean;
  flaky_failure_count: number;
  flaky_window_seconds: number;
  reliability_target: number;
  enabled: boolean;
  current_status: ServiceStatus;
  status_reason: string | null;
  status_since: string | null;
  consecutive_failures: number;
  consecutive_successes: number;
  last_checked_at: string | null;
  last_success_at: string | null;
  last_failure_at: string | null;
}

export type ServiceConfig = Pick<
  Service,
  | "criticality" | "health_url" | "owner" | "check_interval_seconds" | "timeout_ms" | "slow_threshold_ms"
  | "failure_threshold" | "recovery_threshold" | "flaky_enabled" | "flaky_failure_count"
  | "flaky_window_seconds" | "reliability_target" | "enabled"
>;

export interface HealthCheck {
  id: number;
  scheduled_at: string;
  started_at: string;
  completed_at: string;
  outcome: "OK_FAST" | "OK_SLOW" | "FAIL_HTTP" | "FAIL_TIMEOUT" | "FAIL_CONNECTION";
  success: boolean;
  http_status: number | null;
  response_time_ms: number | null;
  error_message: string | null;
  resulting_status: ServiceStatus;
}

export interface Availability {
  total_checks: number;
  successful_checks: number;
  covered_minutes: number;
  window_minutes: number;
  sufficient: boolean;
  percent: number | null;
}

export interface ErrorBudget {
  allowed_minutes: number;
  used_minutes: number;
  remaining_minutes: number;
  remaining_percent: number | null;
  exhausted: boolean;
}

export interface Reliability {
  window_hours: number;
  availability: Availability;
  error_budget: ErrorBudget | null;
  target: number;
  meets_target: boolean | null;
  latency_avg_ms: number | null;
  latency_p50_ms: number | null;
  latency_p95_ms: number | null;
  flaky_episodes: number;
}

export interface Incident {
  id: number;
  code: string;
  service_id: number;
  service_name: string;
  trigger_type: string;
  trigger_key: string;
  title: string;
  severity: string;
  status: IncidentStatus;
  first_failure_at: string;
  opened_at: string;
  acknowledged_at: string | null;
  acknowledged_by: string | null;
  resolved_at: string | null;
}

export interface TimelineEntry {
  at: string;
  kind: string;
  text: string;
  is_public: boolean;
  details: { http_status?: number | null; response_time_ms?: number | null; outcome?: string; error?: string | null } | null;
}

export interface NotificationDelivery {
  event_type: string;
  delivery_status: "PENDING" | "DELIVERED" | "FAILED";
  attempts: number;
  last_attempt_at: string | null;
  last_http_status: number | null;
  last_error: string | null;
}

export interface IncidentDetail extends Incident {
  timeline: TimelineEntry[];
  notifications: NotificationDelivery[];
}

export interface DashboardServiceRow {
  service: Service;
  reliability: Reliability;
  last_check: HealthCheck | null;
  recent: { at: string; ms: number | null; ok: boolean }[];
}

export interface DashboardSummary {
  total_services: number;
  by_status: Record<ServiceStatus, number>;
  active_incidents: Incident[];
  recent_incidents: Incident[];
  services: DashboardServiceRow[];
}

export interface MetricsSummary {
  incidents_total: number;
  mttd_seconds: number | null;
  mtta_seconds: number | null;
  mttr_seconds: number | null;
  checks_24h: number;
  check_success_rate_24h: number | null;
  avg_response_ms_24h: number | null;
  check_duration_avg_ms_1h: number | null;
  scheduler_lag_p95_ms_1h: number | null;
  notifications: { delivered: number; failed: number; pending: number };
  notification_success_rate: number | null;
  flaky_episodes_24h: number;
}

// ---- public (customer-safe) ----
export interface PublicIncident {
  id: string;
  service: string;
  message: string;
  state: "Investigating" | "Recovering" | "Resolved";
  started_at: string;
  resolved_at: string | null;
  duration_minutes: number | null;
  latest_update: { at: string; text: string } | null;
}

export interface PublicService {
  name: string;
  status: string;
  message: string;
  since: string | null;
  active_incidents: PublicIncident[];
}

export interface PublicStatus {
  overall: string;
  updated_at: string;
  services: PublicService[];
}

export interface PublicHistory {
  days: number;
  incidents: PublicIncident[];
}

// The ONLY place that talks to the backend. Every screen calls these functions.
// Same origin as the API, so the browser sends the session cookie automatically.
import type {
  DashboardSummary, HealthCheck, Incident, IncidentDetail, MetricsSummary, PublicHistory, PublicStatus,
  Reliability, Service, ServiceConfig,
} from "./types";

export class ApiError extends Error {
  constructor(public status: number, public messages: string[]) {
    super(messages.join("; "));
  }
}

/** FastAPI errors look like {"detail": "text"} or {"detail": ["a", "b"]} or pydantic's [{msg, loc}]. */
function toMessages(detail: unknown): string[] {
  if (typeof detail === "string") return [detail];
  if (Array.isArray(detail)) {
    return detail.map((d) => (typeof d === "string" ? d : `${(d.loc ?? []).slice(1).join(".")}: ${d.msg}`));
  }
  return ["Unexpected error"];
}

async function request<T>(method: string, path: string, body?: unknown): Promise<T> {
  const res = await fetch(path, {
    method,
    credentials: "same-origin",
    headers: body === undefined ? undefined : { "Content-Type": "application/json" },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  if (!res.ok) {
    const data = await res.json().catch(() => ({}));
    if (res.status === 401 && !path.startsWith("/api/auth/")) {
      // Session expired or logged out elsewhere: let the auth provider send the user to /login.
      window.dispatchEvent(new Event("pulse:unauthorized"));
    }
    throw new ApiError(res.status, toMessages(data.detail));
  }
  return res.json() as Promise<T>;
}

export const api = {
  // auth
  me: () => request<{ user: string }>("GET", "/api/auth/me"),
  login: (username: string, password: string) =>
    request<{ user: string }>("POST", "/api/auth/login", { username, password }),
  logout: () => request<{ ok: boolean }>("POST", "/api/auth/logout"),

  // operator
  dashboard: () => request<DashboardSummary>("GET", "/api/dashboard/summary"),
  metrics: () => request<MetricsSummary>("GET", "/api/metrics/summary"),
  service: (id: number) => request<Service>("GET", `/api/services/${id}`),
  serviceChecks: (id: number, limit = 100) => request<HealthCheck[]>("GET", `/api/services/${id}/checks?limit=${limit}`),
  serviceMetrics: (id: number) => request<Reliability>("GET", `/api/services/${id}/metrics`),
  createService: (data: { name: string; description: string; health_url: string; owner: string; criticality: string }) =>
    request<Service>("POST", "/api/services", data),
  updateService: (id: number, data: Partial<ServiceConfig>) => request<Service>("PATCH", `/api/services/${id}`, data),
  incidents: (params: { status?: string; service_id?: number } = {}) => {
    const q = new URLSearchParams();
    if (params.status) q.set("status", params.status);
    if (params.service_id) q.set("service_id", String(params.service_id));
    return request<Incident[]>("GET", `/api/incidents?${q}`);
  },
  incident: (id: number) => request<IncidentDetail>("GET", `/api/incidents/${id}`),
  acknowledge: (id: number) => request<IncidentDetail>("POST", `/api/incidents/${id}/acknowledge`),
  addNote: (id: number, note: string) => request<IncidentDetail>("POST", `/api/incidents/${id}/notes`, { note }),

  // public (no login)
  publicStatus: () => request<PublicStatus>("GET", "/api/public/status"),
  publicHistory: (days = 7) => request<PublicHistory>("GET", `/api/public/history?days=${days}`),
};

