// Small pure display helpers (unit-tested in format.test.ts).

/** "14:02:10" in the browser's time zone; with date: "18 Nov, 14:02:10". "–" for missing values. */
export function fmtTime(iso: string | null | undefined, withDate = false): string {
  if (!iso) return "–";
  const d = new Date(iso);
  const time = d.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false });
  if (!withDate) return time;
  return `${d.toLocaleDateString(undefined, { day: "2-digit", month: "short" })}, ${time}`;
}

/** 42 -> "42s", 125 -> "2m 5s", 3720 -> "1h 2m". */
export function fmtDuration(seconds: number | null | undefined): string {
  if (seconds === null || seconds === undefined) return "–";
  const s = Math.max(0, Math.round(seconds));
  if (s < 60) return `${s}s`;
  if (s < 3600) return `${Math.floor(s / 60)}m ${s % 60}s`;
  return `${Math.floor(s / 3600)}h ${Math.floor((s % 3600) / 60)}m`;
}

export function secondsBetween(fromIso: string, toIso: string | null): number | null {
  if (!toIso) return null;
  return (new Date(toIso).getTime() - new Date(fromIso).getTime()) / 1000;
}

export function fmtPercent(value: number | null | undefined, digits = 2): string {
  return value === null || value === undefined ? "–" : `${value.toFixed(digits)} %`;
}

/** Tailwind classes for a status pill. Covers operator states, incident states and public labels. */
export function statusColor(status: string): string {
  switch (status) {
    case "HEALTHY": case "Operational": case "RESOLVED_OK": case "DELIVERED": case "Resolved":
      return "bg-green-700";
    case "DEGRADED": case "Degraded performance":
      return "bg-amber-600";
    case "DOWN": case "Service disruption": case "OPEN": case "Investigating": case "FAILED":
      return "bg-red-700";
    case "RECOVERING": case "Recovering": case "ACKNOWLEDGED": case "PENDING":
      return "bg-blue-700";
    default:
      return "bg-slate-500";
  }
}

import { describe, expect, it } from "vitest";
import { fmtDuration, fmtPercent, secondsBetween, statusColor } from "./format";

describe("format helpers", () => {
  it("formats durations", () => {
    expect(fmtDuration(null)).toBe("–");
    expect(fmtDuration(42)).toBe("42s");
    expect(fmtDuration(125)).toBe("2m 5s");
    expect(fmtDuration(3720)).toBe("1h 2m");
  });

  it("formats percentages and missing data", () => {
    expect(fmtPercent(99.9123, 3)).toBe("99.912 %");
    expect(fmtPercent(null)).toBe("–");
  });

  it("computes seconds between timestamps", () => {
    expect(secondsBetween("2026-11-18T13:00:00Z", "2026-11-18T13:04:00Z")).toBe(240);
    expect(secondsBetween("2026-11-18T13:00:00Z", null)).toBeNull();
  });

  it("maps every state to a colour", () => {
    expect(statusColor("DOWN")).toBe("bg-red-700");
    expect(statusColor("Service disruption")).toBe("bg-red-700");
    expect(statusColor("HEALTHY")).toBe("bg-green-700");
    expect(statusColor("RECOVERING")).toBe("bg-blue-700");
    expect(statusColor("UNKNOWN")).toBe("bg-slate-500");
  });
});

import { useCallback, useEffect, useRef, useState } from "react";

/**
 * Loads data now and again every `intervalMs` (the screens show live status).
 * Returns the latest data, the latest error, and `reload` to refresh right after an action.
 * A slow response can't overwrite a newer one: each call has a sequence number.
 */
export function usePoll<T>(load: () => Promise<T>, intervalMs: number, deps: unknown[] = []) {
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState<string | null>(null);
  const seq = useRef(0);

  // eslint-disable-next-line react-hooks/exhaustive-deps
  const reload = useCallback(async () => {
    const mine = ++seq.current;
    try {
      const result = await load();
      if (mine === seq.current) {
        setData(result);
        setError(null);
      }
    } catch (e) {
      if (mine === seq.current) setError(e instanceof Error ? e.message : String(e));
    }
  }, deps);

  useEffect(() => {
    reload();
    const timer = window.setInterval(reload, intervalMs);
    return () => window.clearInterval(timer);
  }, [reload, intervalMs]);

  return { data, error, reload };
}

import { createContext, useCallback, useContext, useEffect, useState, type ReactNode } from "react";
import { Navigate, useLocation } from "react-router-dom";
import { api } from "./api";

// Who is logged in. The real check happens on the server (session cookie); this only drives the UI.
interface AuthState {
  user: string | null;
  loading: boolean;
  login: (username: string, password: string) => Promise<void>;
  logout: () => Promise<void>;
}

const AuthContext = createContext<AuthState | null>(null);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    api.me().then((r) => setUser(r.user)).catch(() => setUser(null)).finally(() => setLoading(false));
    // api.ts fires this when any operator call returns 401 (e.g. the session expired).
    const onUnauthorized = () => setUser(null);
    window.addEventListener("pulse:unauthorized", onUnauthorized);
    return () => window.removeEventListener("pulse:unauthorized", onUnauthorized);
  }, []);

  const login = useCallback(async (username: string, password: string) => {
    const r = await api.login(username, password);
    setUser(r.user);
  }, []);

  const logout = useCallback(async () => {
    await api.logout().catch(() => undefined);
    setUser(null);
  }, []);

  return <AuthContext.Provider value={{ user, loading, login, logout }}>{children}</AuthContext.Provider>;
}

export function useAuth(): AuthState {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be used inside <AuthProvider>");
  return ctx;
}

/** Wraps operator screens: sends anonymous visitors to /login and brings them back afterwards. */
export function RequireAuth({ children }: { children: ReactNode }) {
  const { user, loading } = useAuth();
  const location = useLocation();
  if (loading) return <p className="muted p-6">Loading…</p>;
  if (!user) return <Navigate to="/login" replace state={{ from: location.pathname }} />;
  return <>{children}</>;
}

// Small presentational components shared by several screens.
import type { ReactNode } from "react";
import { statusColor } from "../format";

export function StatusBadge({ status, title }: { status: string; title?: string }) {
  return (
    <span title={title} className={`inline-block rounded-full px-2 py-0.5 text-xs font-semibold text-white ${statusColor(status)}`}>
      {status}
    </span>
  );
}

export function StatCard({ label, value, hint, tone }: { label: string; value: ReactNode; hint?: string; tone?: string }) {
  return (
    <div className="card">
      <div className={`text-2xl font-bold ${tone ?? ""}`}>{value}</div>
      <div className="mt-1 text-xs uppercase tracking-wide text-slate-500">{label}</div>
      {hint && <div className="muted mt-1">{hint}</div>}
    </div>
  );
}

export function ErrorBox({ messages }: { messages: string | string[] | null }) {
  if (!messages || (Array.isArray(messages) && messages.length === 0)) return null;
  const list = Array.isArray(messages) ? messages : [messages];
  return (
    <div className="mb-3 rounded-md border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700" role="alert">
      {list.map((m) => <div key={m}>{m}</div>)}
    </div>
  );
}

