import { Link } from "react-router-dom";
import { api } from "../api";
import { Sparkline } from "../components/ResponseChart";
import { ErrorBox, Loading, StatCard, StatusBadge } from "../components/ui";
import { fmtDuration, fmtPercent, fmtTime } from "../format";
import type { Incident } from "../types";
import { usePoll } from "../usePoll";

// Screen 1: what's healthy and what isn't, at a glance. Refreshes every 5 s.
export function DashboardPage() {
  const dash = usePoll(api.dashboard, 5000);
  const metrics = usePoll(api.metrics, 10000);
  const d = dash.data;
  const m = metrics.data;

  if (!d) return dash.error ? <ErrorBox messages={dash.error} /> : <Loading />;

  return (
    <div>
      <h1 className="h1">Operator dashboard <span className="muted font-normal">live, refreshes every 5 s</span></h1>
      <ErrorBox messages={dash.error} />

      <div className="grid grid-cols-2 gap-3 md:grid-cols-6">
        <StatCard label="Services" value={d.total_services} />
        <StatCard label="Healthy" value={d.by_status.HEALTHY} tone="text-green-700" />
        <StatCard label="Degraded" value={d.by_status.DEGRADED} tone="text-amber-600" />
        <StatCard label="Down" value={d.by_status.DOWN} tone="text-red-700" />
        <StatCard label="Recovering" value={d.by_status.RECOVERING} tone="text-blue-700" />
        <StatCard label="Active incidents" value={d.active_incidents.length} tone={d.active_incidents.length ? "text-red-700" : ""} />
      </div>

      {d.active_incidents.length > 0 && (
        <>
          <h2 className="h2">Active incidents</h2>
          <IncidentTable incidents={d.active_incidents} onChanged={dash.reload} showAck />
        </>
      )}

      <h2 className="h2">Services</h2>
      <table className="table">
        <thead>
          <tr>
            <th>Service</th><th>Tier</th><th>Status</th><th>Last check</th><th>Recent response times</th>
            <th>Fails / OKs in a row</th><th>Availability (24 h)</th><th>Error budget left</th>
          </tr>
        </thead>
        <tbody>
          {d.services.map(({ service: s, reliability: r, last_check: c, recent }) => (
            <tr key={s.id}>
              <td>
                <Link className="link font-semibold" to={`/services/${s.id}`}>{s.name}</Link>
                <div className="muted">{s.owner}</div>
              </td>
              <td>{s.criticality}<div className="muted">every {s.check_interval_seconds} s</div></td>
              <td>
                <StatusBadge status={s.current_status} />
                {s.status_reason && <div className="muted">{s.status_reason}</div>}
                <div className="muted">since {fmtTime(s.status_since)}</div>
              </td>
              <td className="text-xs">
                {c ? <>{c.http_status ? `HTTP ${c.http_status}` : c.outcome} · {c.response_time_ms} ms<div className="muted">{fmtTime(c.started_at)}</div></>
                   : <span className="muted">no checks yet</span>}
              </td>
              <td><Sparkline points={recent} /></td>
              <td>{s.consecutive_failures} / {s.consecutive_successes}</td>
              <td>
                {r.availability.percent === null ? <span className="muted">no data</span> : (
                  <>
                    <b className={r.meets_target === true ? "text-green-700" : r.meets_target === false ? "text-red-700" : ""}>
                      {fmtPercent(r.availability.percent, 3)}
                    </b>
                    <div className="muted">target {r.target} % · {r.availability.total_checks} checks
                      {!r.availability.sufficient && " · insufficient data"}</div>
                  </>
                )}
              </td>
              <td>
                {r.error_budget ? (
                  <>
                    {r.error_budget.exhausted ? <b className="text-red-700">exhausted</b> : `${r.error_budget.remaining_percent ?? "–"} %`}
                    <div className="muted">{r.error_budget.used_minutes.toFixed(2)} of {r.error_budget.allowed_minutes.toFixed(2)} min used</div>
                  </>
                ) : <span className="muted">–</span>}
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      <h2 className="h2">Product metrics</h2>
      {m ? (
        <div className="grid grid-cols-2 gap-3 md:grid-cols-5">
          <StatCard label="MTTD" value={fmtDuration(m.mttd_seconds)} hint="first failed check → incident" />
          <StatCard label="MTTA" value={fmtDuration(m.mtta_seconds)} hint="incident → acknowledged" />
          <StatCard label="MTTR" value={fmtDuration(m.mttr_seconds)} hint="incident → resolved" />
          <StatCard label="Check success (24 h)" value={fmtPercent(m.check_success_rate_24h)} hint={`${m.checks_24h} checks`} />
          <StatCard label="Avg response (24 h)" value={m.avg_response_ms_24h === null ? "–" : `${m.avg_response_ms_24h} ms`} />
          <StatCard label="Scheduler lag p95 (1 h)" value={m.scheduler_lag_p95_ms_1h === null ? "–" : `${m.scheduler_lag_p95_ms_1h} ms`} hint="is Pulse itself keeping up?" />
          <StatCard label="Check duration avg (1 h)" value={m.check_duration_avg_ms_1h === null ? "–" : `${m.check_duration_avg_ms_1h} ms`} />
          <StatCard label="Webhooks delivered" value={fmtPercent(m.notification_success_rate, 1)}
                    hint={`${m.notifications.delivered} ok · ${m.notifications.failed} failed · ${m.notifications.pending} pending`} />
          <StatCard label="Flaky episodes (24 h)" value={m.flaky_episodes_24h} />
          <StatCard label="Incidents (total)" value={m.incidents_total} />
        </div>
      ) : <Loading />}

      <h2 className="h2">Recent incidents</h2>
      {d.recent_incidents.length ? <IncidentTable incidents={d.recent_incidents} /> : <p className="muted">No incidents yet.</p>}
    </div>
  );
}

export function IncidentTable({ incidents, showAck = false, onChanged }: { incidents: Incident[]; showAck?: boolean; onChanged?: () => void }) {
  return (
    <table className="table">
      <thead>
        <tr><th>Incident</th><th>Service</th><th>Severity</th><th>Status</th><th>First failure</th><th>Resolved</th><th>Title</th>{showAck && <th />}</tr>
      </thead>
      <tbody>
        {incidents.map((i) => (
          <tr key={i.id}>
            <td><Link className="link font-semibold" to={`/incidents/${i.id}`}>{i.code}</Link></td>
            <td>{i.service_name}</td>
            <td>{i.severity}</td>
            <td><StatusBadge status={i.status} />{i.acknowledged_by && <div className="muted">by {i.acknowledged_by}</div>}</td>
            <td className="text-xs">{fmtTime(i.first_failure_at, true)}</td>
            <td className="text-xs">{fmtTime(i.resolved_at, true)}</td>
            <td>{i.title}</td>
            {showAck && (
              <td>
                {i.status === "OPEN" && (
                  <button className="btn" onClick={async () => { await api.acknowledge(i.id).catch(() => undefined); onChanged?.(); }}>
                    Acknowledge
                  </button>
                )}
              </td>
            )}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

