          <StatCard label="Check duration avg (1 h)" value={m.check_duration_avg_ms_1h === null ? "–" : `${m.check_duration_avg_ms_1h} ms`} />
          <StatCard label="Webhooks delivered" value={fmtPercent(m.notification_success_rate, 1)}
                    hint={`${m.notifications.delivered} ok · ${m.notifications.failed} failed · ${m.notifications.pending} pending`} />
          <StatCard label="Flaky episodes (24 h)" value={m.flaky_episodes_24h} />
          <StatCard label="Incidents (total)" value={m.incidents_total} />
        </div>
      ) : <Loading />}

      <h2 className="h2">Recent incidents</h2>
      {d.recent_incidents.length ? <IncidentTable incidents={d.recent_incidents} /> : <p className="muted">No incidents yet.</p>}
    </div>
  );
}

export function IncidentTable({ incidents, showAck = false, onChanged }: { incidents: Incident[]; showAck?: boolean; onChanged?: () => void }) {
  return (
    <table className="table">
      <thead>
        <tr><th>Incident</th><th>Service</th><th>Severity</th><th>Status</th><th>First failure</th><th>Resolved</th><th>Title</th>{showAck && <th />}</tr>
      </thead>
      <tbody>
        {incidents.map((i) => (
          <tr key={i.id}>
            <td><Link className="link font-semibold" to={`/incidents/${i.id}`}>{i.code}</Link></td>
            <td>{i.service_name}</td>
            <td>{i.severity}</td>
            <td><StatusBadge status={i.status} />{i.acknowledged_by && <div className="muted">by {i.acknowledged_by}</div>}</td>
            <td className="text-xs">{fmtTime(i.first_failure_at, true)}</td>
            <td className="text-xs">{fmtTime(i.resolved_at, true)}</td>
            <td>{i.title}</td>
            {showAck && (
              <td>
                {i.status === "OPEN" && (
                  <button className="btn" onClick={async () => { await api.acknowledge(i.id).catch(() => undefined); onChanged?.(); }}>
                    Acknowledge
                  </button>
                )}
              </td>
            )}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

