import { useEffect, useState, type FormEvent } from "react";
import { useParams } from "react-router-dom";
import { api, ApiError } from "../api";
import { ResponseChart } from "../components/ResponseChart";
import { ErrorBox, Loading, StatCard, StatusBadge } from "../components/ui";
import { fmtPercent, fmtTime } from "../format";
import type { Service, ServiceConfig } from "../types";
import { usePoll } from "../usePoll";
import { IncidentTable } from "./Dashboard";

// Screen 2: one service: live state, chart, check history (with exact errors), reliability, config.
export function ServicePage() {
  const id = Number(useParams().id);
  const service = usePoll(() => api.service(id), 5000, [id]);
  const checks = usePoll(() => api.serviceChecks(id, 100), 5000, [id]);
  const rel = usePoll(() => api.serviceMetrics(id), 10000, [id]);
  const incidents = usePoll(() => api.incidents({ service_id: id }), 10000, [id]);

  const s = service.data;
  if (!s) return service.error ? <ErrorBox messages={service.error} /> : <Loading />;
  const r = rel.data;
  const points = [...(checks.data ?? [])].reverse().map((c) => ({ at: c.started_at, ms: c.response_time_ms, ok: c.success }));

  return (
    <div>
      <h1 className="h1 flex items-center gap-3">
        {s.name} <StatusBadge status={s.current_status} />
        {s.status_reason && <span className="muted font-normal">{s.status_reason}</span>}
        {!s.enabled && <StatusBadge status="PAUSED" />}
      </h1>
      <p className="muted -mt-3 mb-4">{s.description} · owner <b>{s.owner}</b> · <code>{s.health_url}</code></p>

      <div className="grid grid-cols-2 gap-3 md:grid-cols-6">
        <StatCard label="Consecutive failures" value={s.consecutive_failures} hint={`DOWN at ${s.failure_threshold}`} />
        <StatCard label="Consecutive successes" value={s.consecutive_successes} hint={`recovered at ${s.recovery_threshold}`} />
        <StatCard label="Last success" value={<span className="text-sm">{fmtTime(s.last_success_at, true)}</span>} />
        <StatCard label="Last failure" value={<span className="text-sm">{fmtTime(s.last_failure_at, true)}</span>} />
        <StatCard label={`Availability ${r?.window_hours ?? 24} h`} value={fmtPercent(r?.availability.percent, 3)}
                  hint={r ? `target ${r.target} % · ${r.availability.successful_checks}/${r.availability.total_checks} checks` : undefined}
                  tone={r?.meets_target === false ? "text-red-700" : r?.meets_target ? "text-green-700" : ""} />
        <StatCard label="Error budget left"
                  value={r?.error_budget ? (r.error_budget.exhausted ? "exhausted" : `${r.error_budget.remaining_percent ?? "–"} %`) : "–"}
                  hint={r?.error_budget ? `${r.error_budget.used_minutes.toFixed(3)} of ${r.error_budget.allowed_minutes.toFixed(3)} min used` : undefined}
                  tone={r?.error_budget?.exhausted ? "text-red-700" : ""} />
      </div>
      {r && (
        <p className="muted mt-2">
          Availability = successful ÷ all checks in the last {r.window_hours} h, covering {r.availability.covered_minutes.toFixed(1)} of {r.availability.window_minutes} min
          {!r.availability.sufficient && " (insufficient data: at least 10 checks needed)"}. Sampled checks can miss outages shorter than the
          interval; time when Pulse was not running is missing data, not healthy. Latency avg {r.latency_avg_ms ?? "–"} ms · p50 {r.latency_p50_ms ?? "–"} ms ·
          p95 {r.latency_p95_ms ?? "–"} ms · flaky episodes {r.flaky_episodes}.
        </p>
      )}

      <h2 className="h2">Response time (last {points.length} checks)</h2>
      <div className="card"><ResponseChart points={points} slowThresholdMs={s.slow_threshold_ms} /></div>

      <div className="mt-2 grid gap-6 lg:grid-cols-2">
        <div>
          <h2 className="h2">Monitoring configuration</h2>
          <ConfigForm service={s} onSaved={service.reload} />
        </div>
        <div>
          <h2 className="h2">Incidents for this service</h2>
          {incidents.data?.length ? <IncidentTable incidents={incidents.data} /> : <p className="muted">No incidents.</p>}
        </div>
      </div>

      <h2 className="h2">Recent health checks <span className="muted font-normal">technical detail, operators only</span></h2>
      <table className="table">
        <thead><tr><th>Started</th><th>Outcome</th><th>HTTP</th><th>Response</th><th>Lag</th><th>Status after</th><th>Error</th></tr></thead>
        <tbody>
          {(checks.data ?? []).slice(0, 50).map((c) => (
            <tr key={c.id}>
              <td className="text-xs">{fmtTime(c.started_at)}</td>
              <td><StatusBadge status={c.outcome === "OK_FAST" ? "HEALTHY" : c.outcome === "OK_SLOW" ? "DEGRADED" : "DOWN"} title={c.outcome} /> <span className="text-xs">{c.outcome}</span></td>
              <td>{c.http_status ?? "–"}</td>
              <td>{c.response_time_ms} ms</td>
              <td className="text-xs">{Math.round(new Date(c.started_at).getTime() - new Date(c.scheduled_at).getTime())} ms</td>
              <td>{c.resulting_status}</td>
              <td className="font-mono text-xs text-red-700">{c.error_message}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

const NUMBER_FIELDS: [keyof ServiceConfig, string][] = [
  ["check_interval_seconds", "Check interval (s)"],
  ["timeout_ms", "Timeout (ms)"],
  ["slow_threshold_ms", "Slow threshold (ms)"],
  ["failure_threshold", "Failures → DOWN"],
  ["recovery_threshold", "Successes → recovered"],
  ["flaky_failure_count", "Flaky: failures (X)"],
  ["flaky_window_seconds", "Flaky: window (Y s)"],
  ["reliability_target", "Reliability target (%)"],
];

function pickConfig(s: Service): ServiceConfig {
  const { criticality, health_url, owner, check_interval_seconds, timeout_ms, slow_threshold_ms, failure_threshold,
          recovery_threshold, flaky_enabled, flaky_failure_count, flaky_window_seconds, reliability_target, enabled } = s;
  return { criticality, health_url, owner, check_interval_seconds, timeout_ms, slow_threshold_ms, failure_threshold,
           recovery_threshold, flaky_enabled, flaky_failure_count, flaky_window_seconds, reliability_target, enabled };
}

/** Edits the monitoring config. The form keeps its own copy so 5-second polling never overwrites typing. */
function ConfigForm({ service, onSaved }: { service: Service; onSaved: () => void }) {
  const [form, setForm] = useState<ServiceConfig>(() => pickConfig(service));
  const [errors, setErrors] = useState<string[]>([]);
  const [saved, setSaved] = useState(false);
  const [busy, setBusy] = useState(false);

  useEffect(() => { setForm(pickConfig(service)); }, [service.id]); // reset only when switching service

  const set = <K extends keyof ServiceConfig>(key: K, value: ServiceConfig[K]) => { setForm({ ...form, [key]: value }); setSaved(false); };

  async function submit(e: FormEvent) {
    e.preventDefault();
    setBusy(true);
    setErrors([]);
    try {
      await api.updateService(service.id, form);
      setSaved(true);
      onSaved();
    } catch (err) {
      setErrors(err instanceof ApiError ? err.messages : [String(err)]);
    } finally {
      setBusy(false);
    }
  }

  return (
    <form onSubmit={submit} className="card">
      <ErrorBox messages={errors} />
      {saved && <div className="mb-3 rounded-md border border-green-200 bg-green-50 px-3 py-2 text-sm text-green-700">Saved. Applies from the next check.</div>}
      <div className="grid grid-cols-2 gap-3 md:grid-cols-3">
        <label className="label">Criticality
          <select className="input mt-1" value={form.criticality} onChange={(e) => set("criticality", e.target.value as ServiceConfig["criticality"])}>
            {["critical", "high", "medium", "low"].map((t) => <option key={t}>{t}</option>)}
          </select>
        </label>
        {NUMBER_FIELDS.map(([key, label]) => (
          <label key={key} className="label">{label}
            <input className="input mt-1" type="number" step={key === "reliability_target" ? "0.001" : "1"} name={key}
                   value={form[key] as number} onChange={(e) => set(key, Number(e.target.value) as never)} />
          </label>
        ))}
        <label className="label">Owner
          <input className="input mt-1" value={form.owner} onChange={(e) => set("owner", e.target.value)} />
        </label>
        <label className="label col-span-2">Health URL
          <input className="input mt-1" value={form.health_url} onChange={(e) => set("health_url", e.target.value)} />
        </label>
        <label className="label flex items-center gap-2"><input type="checkbox" checked={form.flaky_enabled} onChange={(e) => set("flaky_enabled", e.target.checked)} /> Flaky detection on</label>
        <label className="label flex items-center gap-2"><input type="checkbox" checked={form.enabled} onChange={(e) => set("enabled", e.target.checked)} /> Monitoring enabled</label>
      </div>
      <div className="mt-3 flex items-center gap-3">
        <button className="btn" disabled={busy}>{busy ? "Saving…" : "Save configuration"}</button>
        <span className="muted">Rules: slow threshold &lt; timeout &lt; interval · flaky window ≥ X × interval</span>
      </div>
    </form>
  );
}

