import { useState, type FormEvent } from "react";
import { Link, useParams } from "react-router-dom";
import { api, ApiError } from "../api";
import { ErrorBox, Loading, StatCard, StatusBadge } from "../components/ui";
import { fmtDuration, fmtTime, secondsBetween } from "../format";
import { usePoll } from "../usePoll";

// Screen 3: one incident: facts, timeline (with technical errors), webhook delivery, ack and notes.
export function IncidentPage() {
  const id = Number(useParams().id);
  const inc = usePoll(() => api.incident(id), 5000, [id]);
  const [note, setNote] = useState("");
  const [errors, setErrors] = useState<string[]>([]);
  const [busy, setBusy] = useState(false);

  const i = inc.data;
  if (!i) return inc.error ? <ErrorBox messages={inc.error} /> : <Loading />;

  async function run(action: () => Promise<unknown>) {
    setBusy(true);
    setErrors([]);
    try {
      await action();
      await inc.reload();
      return true;
    } catch (err) {
      setErrors(err instanceof ApiError ? err.messages : [String(err)]);
      return false;
    } finally {
