import { useState, type FormEvent } from "react";
import { useNavigate } from "react-router-dom";
import { api, ApiError } from "../api";
import { ErrorBox } from "../components/ui";

const TIERS = [["critical", 10], ["high", 15], ["medium", 20], ["low", 30]] as const;

// Register a new service. The backend fills timeout, thresholds and flaky settings from the tier.
export function NewServicePage() {
  const navigate = useNavigate();
  const [form, setForm] = useState({ name: "", description: "", health_url: "http://", owner: "", criticality: "medium" });
  const [errors, setErrors] = useState<string[]>([]);
  const [busy, setBusy] = useState(false);
  const set = (key: keyof typeof form, value: string) => setForm({ ...form, [key]: value });

  async function submit(e: FormEvent) {
    e.preventDefault();
    setBusy(true);
    setErrors([]);
    try {
      const svc = await api.createService({ ...form, name: form.name.trim(), health_url: form.health_url.trim() });
      navigate(`/services/${svc.id}`);
    } catch (err) {
      setErrors(err instanceof ApiError ? err.messages : [String(err)]);
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="max-w-xl">
      <h1 className="h1">Add a service</h1>
      <form onSubmit={submit} className="card space-y-3">
        <ErrorBox messages={errors} />
        <label className="label">Name (lowercase, e.g. <code>policies</code>)
          <input className="input mt-1" value={form.name} onChange={(e) => set("name", e.target.value)} required />
        </label>
        <label className="label">Description
          <input className="input mt-1" value={form.description} onChange={(e) => set("description", e.target.value)} />
        </label>
        <label className="label">Health URL
          <input className="input mt-1" value={form.health_url} onChange={(e) => set("health_url", e.target.value)} required />
        </label>
        <label className="label">Owner (team)
          <input className="input mt-1" value={form.owner} onChange={(e) => set("owner", e.target.value)} required />
        </label>
        <label className="label">Criticality
          <select className="input mt-1" value={form.criticality} onChange={(e) => set("criticality", e.target.value)}>
            {TIERS.map(([t, s]) => <option key={t} value={t}>{t}: checked every {s} s</option>)}
          </select>
        </label>
        <p className="muted">Timeout, thresholds, flaky detection and the reliability target start from the tier defaults. You can change them on the service page.</p>
        <button className="btn" disabled={busy}>{busy ? "Adding…" : "Add service"}</button>
      </form>
    </div>
  );
}

