import { Link } from "react-router-dom";
import { api } from "../api";
import { ErrorBox, Loading, StatusBadge } from "../components/ui";
import { fmtTime } from "../format";
import { usePoll } from "../usePoll";

// Screen 4: the PUBLIC status page. No login. It only calls /api/public/*, which return
// customer-safe schemas: no error messages, HTTP codes, URLs, owners or notes exist in that data.
export function PublicStatusPage() {
  const status = usePoll(api.publicStatus, 10000);
  const history = usePoll(() => api.publicHistory(7), 30000);
  const s = status.data;

  return (
    <div className="min-h-screen">
      <header className="flex items-center bg-slate-900 px-6 py-3">
        <span className="text-base font-bold text-white">Acko system status</span>
        <Link to="/login" className="ml-auto text-sm text-slate-300 hover:text-white">Operator login</Link>
      </header>
      <main className="mx-auto max-w-3xl px-6 py-6">
        <ErrorBox messages={status.error && "Status is temporarily unavailable. Please try again shortly."} />
        {!s ? <Loading /> : (
          <>
            <div className="card mb-4">
              <h1 className="text-xl font-bold">{s.overall}</h1>
              <div className="muted">Updated {fmtTime(s.updated_at, true)} · refreshes every 10 seconds</div>
            </div>

            {s.services.map((svc) => (
              <div key={svc.name} className="card mb-3">
                <div className="flex items-center justify-between">
                  <b className="text-base">{svc.name}</b>
                  <StatusBadge status={svc.status} />
                </div>
                <p className="mt-1 text-sm">{svc.message}</p>
                {svc.since && svc.status !== "Operational" && <div className="muted">Since {fmtTime(svc.since, true)}</div>}
                {svc.active_incidents.map((i) => (
                  <div key={i.id} className="mt-2 rounded-md bg-red-50 p-3 text-sm">
                    <StatusBadge status={i.state} /> <b>{i.id}</b>, started {fmtTime(i.started_at, true)}
                    <div className="mt-1">{i.message}</div>
                    {i.latest_update && <div className="muted mt-1">Latest update ({fmtTime(i.latest_update.at)}): {i.latest_update.text}</div>}
                  </div>
                ))}
              </div>
            ))}
          </>
        )}

        <h2 className="h2">Incident history (last 7 days)</h2>
        {!history.data ? <Loading /> : history.data.incidents.length === 0 ? <p className="muted">No incidents in the last 7 days.</p> : (
          <table className="table">
            <thead><tr><th>Service</th><th>Incident</th><th>Started</th><th>State</th><th>Duration</th><th>Latest update</th></tr></thead>
            <tbody>
              {history.data.incidents.map((i) => (
                <tr key={i.id}>
                  <td>{i.service}</td><td>{i.id}</td><td className="text-xs">{fmtTime(i.started_at, true)}</td>
                  <td><StatusBadge status={i.state} /></td>
                  <td>{i.duration_minutes === null ? "ongoing" : `${i.duration_minutes} min`}</td>
                  <td className="text-xs">{i.latest_update?.text}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </main>
    </div>
  );
}

