import { useState, type FormEvent } from "react";
import { Link, useParams } from "react-router-dom";
import { api, ApiError } from "../api";
import { ErrorBox, Loading, StatCard, StatusBadge } from "../components/ui";
import { fmtDuration, fmtTime, secondsBetween } from "../format";
import { usePoll } from "../usePoll";

// Screen 3: one incident: facts, timeline (with technical errors), webhook delivery, ack and notes.
export function IncidentPage() {
  const id = Number(useParams().id);
  const inc = usePoll(() => api.incident(id), 5000, [id]);
  const [note, setNote] = useState("");
  const [errors, setErrors] = useState<string[]>([]);
  const [busy, setBusy] = useState(false);

  const i = inc.data;
  if (!i) return inc.error ? <ErrorBox messages={inc.error} /> : <Loading />;

  async function run(action: () => Promise<unknown>) {
    setBusy(true);
    setErrors([]);
    try {
      await action();
      await inc.reload();
      return true;
    } catch (err) {
      setErrors(err instanceof ApiError ? err.messages : [String(err)]);
      return false;
    } finally {
      setBusy(false);
    }
  }

  async function submitNote(e: FormEvent) {
    e.preventDefault();
    if (await run(() => api.addNote(id, note))) setNote("");
  }

  return (
    <div>
      <h1 className="h1 flex items-center gap-3">
        {i.code} · <Link className="link" to={`/services/${i.service_id}`}>{i.service_name}</Link>
        <StatusBadge status={i.status} /> <span className="muted font-normal">{i.severity}</span>
      </h1>
      <p className="-mt-2 mb-4 font-semibold">{i.title}</p>
      <ErrorBox messages={errors} />

      <div className="grid grid-cols-2 gap-3 md:grid-cols-4">
        <StatCard label="First failed check" value={<span className="text-sm">{fmtTime(i.first_failure_at, true)}</span>} />
        <StatCard label="Opened" value={<span className="text-sm">{fmtTime(i.opened_at, true)}</span>}
                  hint={`detected after ${fmtDuration(secondsBetween(i.first_failure_at, i.opened_at))}`} />
        <StatCard label="Acknowledged" value={<span className="text-sm">{fmtTime(i.acknowledged_at, true)}</span>}
                  hint={i.acknowledged_by ? `by ${i.acknowledged_by}` : undefined} />
        <StatCard label="Resolved" value={<span className="text-sm">{fmtTime(i.resolved_at, true)}</span>}
                  hint={i.resolved_at ? `after ${fmtDuration(secondsBetween(i.opened_at, i.resolved_at))}` : "resolves automatically on confirmed recovery"} />
      </div>
      <p className="muted mt-2">Trigger <code>{i.trigger_type}</code> · key <code>{i.trigger_key}</code></p>

      {i.status !== "RESOLVED" && (
        <div className="card mt-4">
          {i.status === "OPEN" && (
            <button className="btn mb-3" disabled={busy} onClick={() => run(() => api.acknowledge(id))}>Acknowledge</button>
          )}
          <form onSubmit={submitNote}>
            <label className="label">Add an internal note (never shown to customers)
              <textarea className="input mt-1" rows={2} maxLength={2000} value={note} onChange={(e) => setNote(e.target.value)} required />
            </label>
            <button className="btn mt-2" disabled={busy || !note.trim()}>Add note</button>
          </form>
        </div>
      )}

      <h2 className="h2">Timeline</h2>
      <ul className="card divide-y divide-dashed divide-slate-200 p-0">
        {i.timeline.map((e, n) => (
          <li key={n} className="flex gap-4 px-4 py-2 text-sm">
            <span className="w-36 shrink-0 font-mono text-xs text-slate-500">{fmtTime(e.at, true)}</span>
            <span className="w-44 shrink-0 font-semibold">
              {e.kind}{e.is_public && <span className="ml-2 rounded bg-green-100 px-1 text-xs text-green-800" title="shown on the public status page">public</span>}
            </span>
            <span>
              {e.text}
              {e.details && (
                <div className="font-mono text-xs text-slate-500">
                  {e.details.http_status ? `HTTP ${e.details.http_status} · ` : ""}
                  {e.details.response_time_ms !== null && e.details.response_time_ms !== undefined ? `${e.details.response_time_ms} ms · ` : ""}
                  {e.details.outcome}
                  {e.details.error && <div className="text-red-700">{e.details.error}</div>}
                </div>
              )}
            </span>
          </li>
        ))}
      </ul>

      <h2 className="h2">Webhook notifications</h2>
      {i.notifications.length ? (
        <table className="table">
          <thead><tr><th>Event</th><th>Delivery</th><th>Attempts</th><th>Last attempt</th><th>HTTP</th><th>Last error</th></tr></thead>
          <tbody>
            {i.notifications.map((n) => (
              <tr key={n.event_type}>
                <td>{n.event_type}</td><td><StatusBadge status={n.delivery_status} /></td><td>{n.attempts}</td>
                <td className="text-xs">{fmtTime(n.last_attempt_at, true)}</td><td>{n.last_http_status ?? "–"}</td>
                <td className="font-mono text-xs">{n.last_error}</td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : <p className="muted">None.</p>}
    </div>
  );
}

import { useState, type FormEvent } from "react";
import { useNavigate } from "react-router-dom";
import { api, ApiError } from "../api";
import { ErrorBox } from "../components/ui";

const TIERS = [["critical", 10], ["high", 15], ["medium", 20], ["low", 30]] as const;

// Register a new service. The backend fills timeout, thresholds and flaky settings from the tier.
export function NewServicePage() {
  const navigate = useNavigate();
  const [form, setForm] = useState({ name: "", description: "", health_url: "http://", owner: "", criticality: "medium" });
  const [errors, setErrors] = useState<string[]>([]);
  const [busy, setBusy] = useState(false);
  const set = (key: keyof typeof form, value: string) => setForm({ ...form, [key]: value });

  async function submit(e: FormEvent) {
    e.preventDefault();
    setBusy(true);
    setErrors([]);
    try {
      const svc = await api.createService({ ...form, name: form.name.trim(), health_url: form.health_url.trim() });
      navigate(`/services/${svc.id}`);
    } catch (err) {
      setErrors(err instanceof ApiError ? err.messages : [String(err)]);
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="max-w-xl">
      <h1 className="h1">Add a service</h1>
      <form onSubmit={submit} className="card space-y-3">
        <ErrorBox messages={errors} />
        <label className="label">Name (lowercase, e.g. <code>policies</code>)
          <input className="input mt-1" value={form.name} onChange={(e) => set("name", e.target.value)} required />
        </label>
        <label className="label">Description
          <input className="input mt-1" value={form.description} onChange={(e) => set("description", e.target.value)} />
        </label>
        <label className="label">Health URL
          <input className="input mt-1" value={form.health_url} onChange={(e) => set("health_url", e.target.value)} required />
        </label>
        <label className="label">Owner (team)
          <input className="input mt-1" value={form.owner} onChange={(e) => set("owner", e.target.value)} required />
        </label>
        <label className="label">Criticality
          <select className="input mt-1" value={form.criticality} onChange={(e) => set("criticality", e.target.value)}>
            {TIERS.map(([t, s]) => <option key={t} value={t}>{t}: checked every {s} s</option>)}
          </select>
        </label>
        <p className="muted">Timeout, thresholds, flaky detection and the reliability target start from the tier defaults. You can change them on the service page.</p>
        <button className="btn" disabled={busy}>{busy ? "Adding…" : "Add service"}</button>
      </form>
    </div>
  );
}

