      </header>
      <main className="mx-auto max-w-3xl px-6 py-6">
        <ErrorBox messages={status.error && "Status is temporarily unavailable. Please try again shortly."} />
        {!s ? <Loading /> : (
          <>
            <div className="card mb-4">
              <h1 className="text-xl font-bold">{s.overall}</h1>
              <div className="muted">Updated {fmtTime(s.updated_at, true)} · refreshes every 10 seconds</div>
